import { ApiProperty } from '@nestjs/swagger';

/**
 * Problem Details object as defined in RFC 7807.
 * This is the canonical error shape returned by every endpoint of the Parkit API.
 *
 * @see https://www.rfc-editor.org/rfc/rfc7807
 */
export class ProblemDetailsDto {
  @ApiProperty({
    description:
      'A short, human-readable summary of the problem type. Stable across occurrences of the same error class.',
    example: 'Conflict',
  })
  title: string;

  @ApiProperty({
    description:
      'The HTTP status code generated by the origin server. Mirrors the response status.',
    example: 409,
    type: 'integer',
  })
  status: number;

  @ApiProperty({
    description:
      'A human-readable explanation specific to this occurrence of the problem.',
    example: 'Email already registered',
  })
  detail: string;

  @ApiProperty({
    description: 'The request path that produced the error.',
    example: '/auth/register',
  })
  instance: string;
}

export class ValidationFieldErrorDto {
  @ApiProperty({
    description: 'Name of the request body field that failed validation.',
    example: 'password',
  })
  field: string;

  @ApiProperty({
    description:
      'Reason the field failed validation (first matching constraint).',
    example: 'password must be longer than or equal to 8 characters',
  })
  reason: string;
}

/**
 * Returned when one or more body fields fail class-validator constraints
 * (HTTP 400). Same shape as `ProblemDetailsDto` plus a `validationsErrors` array
 * with one entry per offending field.
 */
export class ValidationProblemDetailsDto extends ProblemDetailsDto {
  @ApiProperty({
    description: 'Field-level breakdown of the validation failures.',
    type: [ValidationFieldErrorDto],
  })
  validationsErrors: ValidationFieldErrorDto[];
}
